/**
 * Gathers a recent-records window (alerts, scouting, lab, weather, bottling) and returns a JSON-validated, cautious summary with citations. Requires manager session.
 * @summary Grounded manager AI insights summary
 */
export const generateAiInsightsBodyLookbackDaysMax = 90;

export const GenerateAiInsightsBody = zod.object({
  groveId: zod
    .number()
    .nullish()
    .describe(
      "Restrict the gathered window to a single grove. Omit to summarize across the whole estate.",
    ),
  focus: zod
    .enum([
      "pest_disease",
      "weather",
      "harvest_readiness",
      "oil_quality",
      "general",
    ])
    .nullish()
    .describe(
      "Steer the model toward a single concern. Defaults to `general`.",
    ),
  lookbackDays: zod
    .number()
    .min(1)
    .max(generateAiInsightsBodyLookbackDaysMax)
    .nullish()
    .describe("Window of recent records to include (default 14)."),
});

export const GenerateAiInsightsResponse = zod.object({
  summary: zod.string(),
  insights: zod.array(
    zod.object({
      headline: zod.string(),
      body: zod.string(),
      severity: zod.enum(["info", "watch", "action_recommended"]),
      suggestedTaskType: zod.string().nullish(),
      citations: zod.array(
        zod.object({
          recordType: zod.enum([
            "satellite_alert",
            "pest_find",
            "lab_result",
            "weather_log",
            "bottling_run",
            "phenology_event",
            "harvest_event",
            "treatment",
          ]),
          recordId: zod.number(),
          summary: zod.string(),
        }),
      ),
    }),
  ),
  limitations: zod
    .string()
    .describe(
      "Required cautious-language disclaimer explaining what the model could and could not assess.",
    ),
  generatedAt: zod.coerce.date(),
  model: zod.string(),
  recordCounts: zod.record(zod.string(), zod.number()),
});

